async function readReusableSettingsFile(file){
  if(/\.zip$/i.test(file.name)){
    const zip=await JSZip.loadAsync(file),entry=Object.values(zip.files).find(x=>!x.dir&&/(^|\/)案件\.json$/.test(x.name));
    if(!entry)throw Error('案件.jsonが入った案件ZIPを選んでください。');
    return JSON.parse(await entry.async('text'));
  }
  return JSON.parse(await file.text());
}
async function applyReusableSettings(kind,pack){
  const prepared=prepareReusableSettings(pack);
  if(kind==='personal'){writePersonalSettings(prepared);return}
  if(kind!=='project'||!state.project)throw Error('取り込み先の案件がありません。');
  const fields=['types','workCategoryMaster','equipmentGroupMaster','paletteGroupMaster','findingCategories','findingCategorySelection','findingReportDefaults','wordingSets','reportDefaults'];
  const next={...state.project,...Object.fromEntries(fields.map(key=>[key,structuredClone(prepared[key])])),updatedAt:new Date().toISOString()};
  clearTimeout(saveTimer);
  try{await dbPut(next)}catch(e){saveSoon();throw Error('端末に保存できないため、設定は変更しませんでした。空き容量を確認してください。')}
  state.project=next;state.types=next.types;renderAll();
}
