function paletteGroupSettingsHtml(){const groups=paletteGroups();return `<details class="settings-group" id="paletteGroupSettings"><summary>アイコン分類（パレット） <small>${groups.length}分類</small></summary><p class="master-intro">分類の色は、分類ボタンと「分類の色に合わせる」アイコンへ反映します。「個別色」のアイコンは元の色を保ちます。一括で揃える場合は「所属アイコンを分類色に揃える」を押してください。</p><div class="palette-group-master">${groups.map(g=>`<div class="palette-group-row"><input type="color" data-palette-color="${escapeHtml(g.id)}" value="${escapeHtml(g.color)}" aria-label="${escapeHtml(g.name)}の分類色"><input data-palette-name="${escapeHtml(g.id)}" value="${escapeHtml(g.name)}" aria-label="分類名"><button type="button" data-palette-remove="${escapeHtml(g.id)}" ${groups.length===1?'disabled':''}>削除</button><button type="button" data-palette-inherit="${escapeHtml(g.id)}">所属アイコンを分類色に揃える</button></div>`).join('')}</div><button id="addPaletteGroup" type="button" class="btn btn-outline full">＋ アイコン分類を追加</button></details>`}
function bindPaletteGroupSettings(){const groups=paletteGroups();const refresh=()=>{state.project.paletteGroupMaster=groups;syncPaletteColors(state.project);saveSoon();renderAll()};$$('[data-palette-name]').forEach(el=>el.onchange=()=>{const g=groups.find(x=>x.id===el.dataset.paletteName),name=el.value.trim();if(!name||groups.some(x=>x.id!==g.id&&x.name===name)){el.value=g.name;showToast(name?'同じ名前の分類があります':'分類名を入力してください');return}g.name=name;el.value=name;refresh()});$$('[data-palette-color]').forEach(el=>el.onchange=()=>{groups.find(x=>x.id===el.dataset.paletteColor).color=el.value;refresh()});$$('[data-palette-inherit]').forEach(el=>el.onclick=()=>{const group=groups.find(g=>g.id===el.dataset.paletteInherit),used=state.types.filter(t=>(t.paletteGroupId||t.category)===group.id);if(!confirm(`「${group.name}」の${used.length}種類を分類色に揃えます。個別色も分類連動へ変更しますか？`))return;for(const t of used)t.colorMode='group';refresh();environmentSettingsDialog();$('#paletteGroupSettings').open=true;showToast('所属アイコンを分類色に揃えました')});$$('[data-palette-remove]').forEach(el=>el.onclick=()=>removePaletteGroupDialog(el.dataset.paletteRemove));$('#addPaletteGroup').onclick=()=>{const name=prompt('追加するアイコン分類名');if(!name?.trim())return;if(groups.some(x=>x.name===name.trim())){showToast('同じ名前の分類があります');return}groups.push({id:uid('palette'),name:name.trim(),color:'#705ab0'});refresh();environmentSettingsDialog();$('#paletteGroupSettings').open=true}}
function removePaletteGroupDialog(id){const groups=paletteGroups(),target=groups.find(x=>x.id===id),remaining=groups.filter(x=>x.id!==id);if(!target||!remaining.length){showToast('アイコン分類は1つ以上必要です');return}const used=state.types.filter(t=>(t.paletteGroupId||t.category)===id);showModal('アイコン分類を削除',`<p class="master-intro">「${escapeHtml(target.name)}」を削除します。所属する${used.length}種類のアイコンは、選んだ分類に移します。配置済み設備・記録は保持します。分類色に合わせるアイコンは移動先の色になり、個別色は維持します。</p><div class="field"><span>所属アイコンの移動先</span><select id="paletteGroupDestination">${remaining.map(g=>`<option value="${escapeHtml(g.id)}">${escapeHtml(g.name)}</option>`).join('')}</select></div>`,()=>{const to=$('#paletteGroupDestination').value;if(!remaining.some(g=>g.id===to))return;for(const t of used)t.paletteGroupId=to;state.project.paletteGroupMaster=remaining;state.project.types=state.types;if(state.paletteGroup===id){state.paletteGroup=to;clearPlacementMode()}saveSoon();renderAll();environmentSettingsDialog();$('#paletteGroupSettings').open=true;showToast('分類を削除し、所属アイコンを移しました')});$('#modalSave').textContent='削除して移動';$('#modalCancel').onclick=()=>{environmentSettingsDialog();$('#paletteGroupSettings').open=true};$('#modalClose').onclick=$('#modalCancel').onclick}
function paletteTypes(){const group=state.paletteGroup||'favorites';return state.types.filter(t=>t.enabled!==false&&(group==='all'||(group==='favorites'?t.paletteFavorite===true:(t.paletteGroupId||t.category)===group)))}
