function isCountedMarker(m,t=getType(m.typeId)){return m.countIncluded??(t.countByDefault!==false)}
function pageEquipmentCounts(page){const counts=new Map();for(const m of state.project?.markers||[]){if(Number(m.page)!==Number(page))continue;const t=getType(m.typeId);if(!isCountedMarker(m,t))continue;counts.set(t.id,{type:t,count:(counts.get(t.id)?.count||0)+1})}return [...counts.values()].sort((a,b)=>a.type.name.localeCompare(b.type.name,'ja'))}
function renderPageList(){const list=$('#pageList');if(!list)return;const exportBtn=$('#pageCountCsvBtn');if(!state.pdf){list.innerHTML='<div class="list-empty">図面PDFを読み込むとページが表示されます</div>';if(exportBtn)exportBtn.disabled=!(state.project?.markers?.length);return}const markers=state.project?.markers||[];list.innerHTML=Array.from({length:state.pdf.numPages},(_,i)=>{const page=i+1,label=state.project.pageLabels?.[page]||`ページ ${page}`,pageMarks=markers.filter(m=>m.page===page),counts=pageEquipmentCounts(page);const legend=counts.length?counts.map(({type,count})=>`<span class="page-legend-item"><i style="--type-color:${escapeHtml(type.color||'#1769aa')};color:${escapeHtml(type.textColor||(type.category==='light'?'#26394a':'#ffffff'))}">${glyphHtml(type)}</i>${escapeHtml(type.name)} ${count}${escapeHtml(countUnit(type))}</span>`).join(''):'<span class="page-legend-empty">設備なし</span>';return `<div class="page-row ${page===state.pdfPage?'current':''}" data-page="${page}"><div class="page-row-main"><button class="page-jump" type="button"><strong>${escapeHtml(label)}</strong><small>${pageMarks.length}件 ・ ${page} / ${state.pdf.numPages}</small></button><div class="page-legend">${legend}</div></div><button class="page-rename" type="button" title="ページ名を設定" aria-label="${escapeHtml(label)}のページ名を設定">名前</button></div>`}).join('');if(exportBtn)exportBtn.disabled=!markers.length;list.querySelectorAll('.page-jump').forEach(b=>b.onclick=()=>{const page=Number(b.closest('.page-row').dataset.page);renderPage(page)});list.querySelectorAll('.page-rename').forEach(b=>b.onclick=()=>editPageLabel(Number(b.closest('.page-row').dataset.page)))}
function renderPalette(){const pal=$('#iconPalette'),groups=[{id:'favorites',name:'★ 常用'},{id:'all',name:'全て'},...paletteGroups()];if(!groups.some(g=>g.id===state.paletteGroup))state.paletteGroup='favorites';const group=state.paletteGroup,types=paletteTypes();const filters=`<div class="palette-group-controls" role="group" aria-label="設備パレットの分類">${groups.map(g=>`<button type="button" class="palette-group ${g.id===group?'active':''}" data-palette-group="${escapeHtml(g.id)}" aria-pressed="${g.id===group}">${g.color?`<span class="palette-group-dot" style="background:${g.color}" aria-hidden="true"></span>`:''}${escapeHtml(g.name)}</button>`).join('')}<small>☆で常用に登録・★で解除 ／ 分類で表示を切替</small></div>`;pal.innerHTML=filters+types.map(t=>`<div class="palette-tile"><button type="button" class="palette-item ${state.activeType===t.id?'active':''}" data-id="${escapeHtml(t.id)}" data-category="${escapeHtml(t.category)}" title="${escapeHtml(t.name)}"><span class="palette-art" style="--type-color:${escapeHtml(t.color||'#1769aa')};color:${escapeHtml(t.textColor||(t.category==='light'?'#26394a':'#ffffff'))}">${glyphHtml(t)}</span><small>${escapeHtml(t.name)}</small></button><button type="button" class="palette-star ${t.paletteFavorite?'selected':''}" data-palette-favorite="${escapeHtml(t.id)}" aria-pressed="${!!t.paletteFavorite}" aria-label="${escapeHtml(t.name)}を常用${t.paletteFavorite?'から外す':'に登録'}" title="常用${t.paletteFavorite?'から外す':'に登録'}">${t.paletteFavorite?'★':'☆'}</button></div>`).join('');if(!types.length)pal.insertAdjacentHTML('beforeend',`<div class="list-empty palette-empty">${group==='favorites'?'常用アイコンはありません。「全て」を開き、☆で登録してください。':'この分類に表示するアイコンはありません。'}</div>`);pal.querySelectorAll('[data-palette-group]').forEach(b=>b.onclick=()=>{state.paletteGroup=b.dataset.paletteGroup;clearPlacementMode()});pal.querySelectorAll('[data-palette-favorite]').forEach(b=>b.onclick=()=>togglePaletteFavorite(b.dataset.paletteFavorite));pal.querySelectorAll('.palette-item').forEach(b=>b.onclick=()=>{if(state.activeType===b.dataset.id){clearPlacementMode();return}state.activeType=b.dataset.id;renderPalette();$('#modeHint').textContent=`${getType(state.activeType).name}を選択中：図面をタップ`;$('#cancelPlaceBtn').hidden=false;showToast('図面上の位置をタップしてください')})}
function renderFieldPalette(){const root=$('#fieldPalette');if(!root)return;root.innerHTML=fieldBriefingHtml()+FIELD_TYPES.map(t=>`<button type="button" class="field-palette-item ${state.activeFieldType===t.id?'active':''}" data-field-type="${t.id}"><span>${t.icon}</span><small>${t.label}</small></button>`).join('');root.querySelectorAll('[data-briefing-edit]').forEach(b=>b.onclick=()=>editFieldBriefing(b.dataset.briefingEdit));root.querySelectorAll('[data-field-type]').forEach(b=>b.onclick=()=>{state.activeFieldType=state.activeFieldType===b.dataset.fieldType?null:b.dataset.fieldType;renderFieldPalette();$('#modeHint').textContent=state.activeFieldType?`${FIELD_TYPES.find(x=>x.id===state.activeFieldType).label}：図面の場所をタップ`:'現場マークを選んで図面をタップ'})}
function renderMarkers(){const layer=$('#markerLayer');layer.innerHTML='';if(!state.project)return;for(const m of state.project.markers.filter(x=>x.page===state.pdfPage&&(!state.issueFocus||hasReportMarker(x)))){const t=getType(m.typeId),shownSize=Math.max(10,Math.min(120,(Number(m.size)||t.defaultSize||22)*state.zoom));const el=document.createElement('button');el.className=`map-marker ${state.selectedMarker===m.id?'selected':''} ${hasNg(m)?'has-finding':''} ${state.issueFocus&&hasReportMarker(m)?'focus-finding':''} ${state.fieldMode?'context-marker':''}`;el.dataset.id=m.id;el.dataset.category=t.category;el.dataset.labelPosition=m.labelPosition||t.labelPosition||'bottom';el.style.left=`${m.x*100}%`;el.style.top=`${m.y*100}%`;el.style.width=`${shownSize}px`;el.style.height=`${shownSize}px`;el.style.minHeight=`${Math.max(28,shownSize)}px`;el.style.setProperty('--marker-size',`${shownSize}px`);el.style.setProperty('--marker-label-size',`${Math.max(11,Math.min(22,12*Math.sqrt(state.zoom))).toFixed(1)}px`);el.innerHTML=`${markerArtHtml(t,shownSize,`rotate(${m.rotation||0}deg) scale(${m.flipX?-1:1},${m.flipY?-1:1})`)}<span class="ng-dot"></span><span class="marker-id">${escapeHtml(markerTag(m,t))}</span>${m.checked?'<span class="checked-badge" title="点検済み">✓</span>':''}${state.issueFocus&&hasReportMarker(m)?'<span class="focus-mark" aria-label="報告箇所">!</span>':''}${state.issueFocus&&hasMarkerPhoto(m)?'<span class="camera-mark" aria-label="写真あり">▣</span>':''}`;el.title=`${t.name} ${markerTag(m,t)} ${m.memo||''}`;layer.appendChild(el)}if(state.fieldMode){for(const m of (state.project.fieldMarkers||[]).filter(x=>Number(x.page)===Number(state.pdfPage))){const t=FIELD_TYPES.find(x=>x.id===m.type)||FIELD_TYPES[5],el=document.createElement('button');el.type='button';el.dataset.fieldMarkerId=m.id;el.className=`field-map-marker ${m.done?'done':''}`;el.style.left=`${m.x*100}%`;el.style.top=`${m.y*100}%`;el.title=`${t.label}${m.text?`：${m.text}`:''}${m.done?'（完了）':'（未完了）'}`;el.innerHTML=`<span class="field-marker-icon">${t.icon}</span>${m.done?'<span class="field-marker-done">✓</span>':''}<span class="field-marker-label">${escapeHtml(t.label)}${m.borrowing?`【${escapeHtml(m.borrowing.status||'未設定')}】`:''}${m.text?`：${escapeHtml(m.text)}`:''}</span>`;el.onpointerdown=e=>fieldMarkerPointerDown(e,m);el.onclick=e=>{e.stopPropagation();if(el.dataset.dragged){el.dataset.dragged='';return}editFieldMarker(m.id)};layer.appendChild(el)}}renderCounts()}
function renderCounts(){const all=state.project?.markers||[];const done=all.filter(m=>m.checked).length;if(state.fieldMode){const fields=state.project?.fieldMarkers||[],fieldDone=fields.filter(m=>m.done).length;$('#markerCount').textContent=`現場マーク ${fields.length}件 ・ 完了 ${fieldDone}/${fields.length}`;$('#equipmentCount').textContent=fields.length}else{$('#markerCount').textContent=`設備 ${all.length}件 ・ 点検済 ${done}/${all.length}`;$('#equipmentCount').textContent=all.length}}
function saveBasicSettings(){state.project.types=state.types;saveSoon();renderPalette();renderMaster();renderCounts()}
function environmentPackFromProject(project=state.project){const base=state.envSettings||defaultEnvironmentSettings();return {format:'tenken-pwa-settings',schemaVersion:1,name:`${project?.name||'現場点検ノート'} 環境設定`,workCategoryMaster:structuredClone(project?.workCategoryMaster||base.workCategoryMaster),equipmentGroupMaster:structuredClone(project?.equipmentGroupMaster||base.equipmentGroupMaster),paletteGroupMaster:normalizePaletteGroups(project?.paletteGroupMaster||base.paletteGroupMaster),types:normalizePaletteTypes(project?.types||base.types,project?.paletteGroupMaster||base.paletteGroupMaster),findingCategories:structuredClone(project?.findingCategories||base.findingCategories||[]),findingCategorySelection:normalizeFindingCategorySelection(project?project.findingCategorySelection:base.findingCategorySelection),findingReportDefaults:normalizeFindingReportDefaults(project?project.findingReportDefaults:base.findingReportDefaults),wordingSets:structuredClone(project?.wordingSets||base.wordingSets||[]),reportDefaults:structuredClone(project?.reportDefaults||base.reportDefaults||{workContent:''})}}
function exportEnvironmentSettings(){let pack;try{pack=prepareReusableSettings(environmentPackFromProject())}catch(e){showToast('設定を書き出せません：'+e.message);return}const blob=new Blob([JSON.stringify(pack,null,2)],{type:'application/json;charset=utf-8'});downloadBlob(blob,`${safeFilename(pack.name)}.json`);showToast('環境設定ファイルを書き出しました')}

function renderProjectWorkSettings(){const root=$('#projectWorkSettings');if(!root||!state.project)return;const works=normalizeWorkCategories(state.project.workCategoryMaster),selected=state.project.selectedWorkCategories||[];root.innerHTML=`<div class="panel-heading"><div><h2>この案件の作業区分</h2><p>新規作成時の仮設定をここで変更できます</p></div></div><div class="basic-section"><h3>今回の作業区分</h3><p class="master-intro">「指摘・写真」の常用ボタンの表示対象と、速報版報告書の初期値に使います。配置パレットの表示には影響しません。報告書の作業区分は作成時に別途変更できます。</p><div class="work-check-list">${works.map(x=>`<label><input type="checkbox" data-work-selected="${escapeHtml(x.id)}" ${selected.includes(x.id)?'checked':''}>${escapeHtml(x.name)}</label>`).join('')}</div></div>`;root.querySelectorAll('[data-work-selected]').forEach(c=>c.onchange=()=>{state.project.selectedWorkCategories=$$('[data-work-selected]:checked').map(x=>x.dataset.workSelected);saveBasicSettings()});}
function environmentSettingsDialog(){const personal=readPersonalSettings(),works=normalizeWorkCategories(state.project.workCategoryMaster),groups=normalizeEquipmentGroups(state.project.equipmentGroupMaster),wordings=state.project.wordingSets||[];const wordingSections=[{id:'',name:'全設備共通'},...groups].map(g=>{const rows=wordings.filter(w=>(w.equipmentGroupId||'')===g.id);return `<details class="settings-group" ${g.id?'':'open'}><summary>${escapeHtml(g.name)} <small>${rows.length}件</small></summary><div class="basic-master-list">${rows.map(w=>`<div class="wording-edit-row"><select data-wording-severity="${escapeHtml(w.id)}">${(state.project.findingCategories||['要是正','既存不適格','特記事項','参考','注意点']).filter(x=>x!=='メモ'&&x!=='参考写真').map(c=>`<option ${w.severity===c?'selected':''}>${escapeHtml(c)}</option>`).join('')}</select><textarea rows="2" data-wording-text="${escapeHtml(w.id)}" placeholder="報告文言">${escapeHtml(w.text||'')}</textarea><button type="button" data-wording-remove="${escapeHtml(w.id)}">削除</button></div>`).join('')||'<p class="master-intro">文言セットはありません。</p>'}</div><button type="button" class="btn btn-outline full" data-add-wording="${escapeHtml(g.id)}">＋ この分類に文言を追加</button></details>`}).join('');const html=`<div class="settings-intro">設備配置で使うアイコン、各マスタ、文言セットと初期設定パックを管理します。</div><div class="settings-operation-guide"><strong>どこへ反映するかで、操作を選んでください</strong><p>今の案件を変える：下の「設備アイコン設定」「アイコン分類」などを編集して保存します。</p><p>次の物件でも使う：今の案件を整えた後、「今の設定を自分用初期設定にする」を押します。</p><p>共通のひな形を整える：「管理者：基本セット管理」で編集 → 保存 → 基本セットを一式更新します。</p></div><details class="settings-group" id="reusableSettings" open><summary>設定の再利用・自分用初期設定</summary><p class="master-intro">${personal?'新規案件は、この端末に保存した自分用初期設定から作成します。':'自分用初期設定は未保存です。新規案件は管理者の基本セットから作成します。'} 自分用設定は基本セットの更新では上書きしません。</p><div class="environment-actions"><button id="saveEnvironmentDefaults" type="button" class="btn btn-light">今の設定を自分用初期設定にする</button><button id="importEnvironmentSettings" type="button" class="btn btn-primary">他の案件・ファイルから設定を取り込む</button><button id="exportEnvironmentSettings" type="button" class="btn btn-light">この案件の設定を書き出す</button><button id="exportPersonalSettings" type="button" class="btn btn-light" ${personal?'':'disabled'}>自分用初期設定を書き出す</button></div><p class="master-intro">自分用設定はこのブラウザー・端末内に保存します。別の端末では設定JSONを読み込んで取り込み先に「自分用初期設定」を選んでください。</p></details><details class="settings-group" id="projectWorkSection" open><summary>この案件の作業区分</summary><div id="projectWorkSettings"></div></details><details class="settings-group"><summary>設備アイコン設定 <small>${state.types.length}種</small></summary><p class="master-intro">配置メニューに表示するアイコン種別と、記号・色・計測項目などを設定します。</p><div id="environmentIconList" class="master-list"></div><button id="environmentAddIcon" type="button" class="btn btn-outline full">＋ 設備アイコンを追加</button></details>${paletteGroupSettingsHtml()}${findingCategorySettingsHtml()}<details class="settings-group"><summary>作業区分マスタ</summary><div class="basic-master-list">${works.map(x=>`<div class="basic-master-row"><input data-work-name="${escapeHtml(x.id)}" value="${escapeHtml(x.name)}"><button type="button" data-work-remove="${escapeHtml(x.id)}">削除</button></div>`).join('')}</div><button id="addWorkCategory" type="button" class="btn btn-outline full">＋ 作業区分を追加</button></details><details class="settings-group"><summary>設備大分類マスタ</summary><div class="basic-master-list">${groups.map(x=>`<div class="basic-master-row"><input data-group-name="${escapeHtml(x.id)}" value="${escapeHtml(x.name)}"><button type="button" data-group-remove="${escapeHtml(x.id)}">削除</button></div>`).join('')}</div><button id="addEquipmentGroup" type="button" class="btn btn-outline full">＋ 設備大分類を追加</button></details><details class="settings-group" open><summary>指摘文言セット <small>${wordings.length}件</small></summary><p class="master-intro">設備大分類ごとに整理しています。長い文言も複数行で確認できます。文言セットは環境設定ファイルに含まれます。</p>${wordingSections}</details><details class="settings-group"><summary>管理者の基本セット</summary><p class="master-intro">共通のひな形を管理します。現在の案件や保存済みの自分用初期設定には自動適用しません。</p><button id="openBasicPackManager" type="button" class="btn btn-light">管理者：基本セット管理</button></details>`;showModal('環境設定',html,()=>{saveSoon();closeModal()});bindPaletteGroupSettings();$('#editCommonFindingCategories').onclick=editCommonFindingCategories;$('#editFindingReportDefaults').onclick=editFindingReportDefaults;renderProjectWorkSettings();renderMaster();$('#environmentAddIcon').onclick=()=>{state.returnToEnvironment=true;addTypeDialog()};const root=$('.modal-body');root.querySelectorAll('[data-work-name]').forEach(i=>i.onchange=()=>{const w=works.find(x=>x.id===i.dataset.workName);if(i.value.trim())w.name=i.value.trim();state.project.workCategoryMaster=works;saveSoon();environmentSettingsDialog()});root.querySelectorAll('[data-group-name]').forEach(i=>i.onchange=()=>{const g=groups.find(x=>x.id===i.dataset.groupName);if(i.value.trim())g.name=i.value.trim();state.project.equipmentGroupMaster=groups;saveSoon();environmentSettingsDialog();renderMaster()});root.querySelectorAll('[data-wording-text]').forEach(i=>i.onchange=()=>{const w=wordings.find(x=>x.id===i.dataset.wordingText);if(w){w.text=i.value.trim();saveSoon()}});root.querySelectorAll('[data-wording-severity]').forEach(i=>i.onchange=()=>{const w=wordings.find(x=>x.id===i.dataset.wordingSeverity);if(w){w.severity=i.value;saveSoon()}});root.querySelectorAll('[data-wording-remove]').forEach(b=>b.onclick=()=>{state.project.wordingSets=wordings.filter(w=>w.id!==b.dataset.wordingRemove);saveSoon();environmentSettingsDialog()});root.querySelectorAll('[data-add-wording]').forEach(b=>b.onclick=()=>{const text=prompt('指摘文言を入力してください');if(!text?.trim())return;wordings.push({id:uid('wording'),equipmentGroupId:b.dataset.addWording,severity:'要是正',text:text.trim()});state.project.wordingSets=wordings;saveSoon();environmentSettingsDialog()});root.querySelectorAll('[data-work-remove]').forEach(b=>b.onclick=()=>removeWorkCategory(b.dataset.workRemove));root.querySelectorAll('[data-group-remove]').forEach(b=>b.onclick=()=>removeEquipmentGroup(b.dataset.groupRemove));$('#addWorkCategory').onclick=()=>{const name=prompt('追加する作業区分名');if(!name?.trim())return;works.push({id:uid('work'),name:name.trim()});state.project.workCategoryMaster=works;saveSoon();environmentSettingsDialog()};$('#addEquipmentGroup').onclick=()=>{const name=prompt('追加する設備大分類名');if(!name?.trim())return;groups.push({id:uid('group'),name:name.trim()});state.project.equipmentGroupMaster=groups;saveSoon();environmentSettingsDialog();renderMaster()};$('#saveEnvironmentDefaults').onclick=savePersonalDefaults;$('#exportEnvironmentSettings').onclick=exportEnvironmentSettings;$('#exportPersonalSettings').onclick=exportPersonalSettings;$('#importEnvironmentSettings').onclick=()=>settingsReuse.open();$('#openBasicPackManager').onclick=()=>{closeModal();basicPackManager.open()}}

function removeWorkCategory(id){if(state.project.workCategoryMaster.length<=1){showToast('作業区分は1つ以上必要です');return}if(!confirm('この作業区分をマスタから削除しますか？'))return;state.project.workCategoryMaster=state.project.workCategoryMaster.filter(x=>x.id!==id);state.project.selectedWorkCategories=(state.project.selectedWorkCategories||[]).filter(x=>x!==id);for(const t of state.types){t.workCategoryIds=(t.workCategoryIds||[]).filter(x=>x!==id);for(const q of t.quickFindings||[])q.workCategoryIds=(q.workCategoryIds||[]).filter(x=>x!==id)}if(!state.project.selectedWorkCategories.length)state.project.selectedWorkCategories=[state.project.workCategoryMaster[0].id];saveBasicSettings();environmentSettingsDialog()}
function removeEquipmentGroup(id){if(state.project.equipmentGroupMaster.length<=1){showToast('設備大分類は1つ以上必要です');return}if(!confirm('この大分類を削除しますか？所属アイコンは別の大分類へ移します。'))return;const fallback=state.project.equipmentGroupMaster.find(x=>x.id!==id).id;state.project.equipmentGroupMaster=state.project.equipmentGroupMaster.filter(x=>x.id!==id);for(const t of state.types)if(t.majorGroupId===id)t.majorGroupId=fallback;saveBasicSettings();environmentSettingsDialog()}
function markerResultSummary(m,t){if(t.form==='door'){const parts=m.components||[];const completed=parts.filter(c=>c.time!==''||c.force!==''||c.hazard).length;const values=parts.map(c=>`${c.label||'扉'} ${c.time?`${c.time}秒`:'秒未入力'} / ${c.force?`${c.force}N`:'力未入力'} / 危害 ${c.hazard||'未入力'}`).join(' ｜ ');return parts.length?`扉測定 ${completed}/${parts.length}枚　${values}`:'扉測定欄なし'}if(t.form==='smokeOutlet'){const avg=average(m.velocities||[]);const area=calcAreaRaw(m.height,m.width);return `風速平均 ${avg===null?'未計算':`${avg.toFixed(2)}m/s`} ・ 開口面積 ${area?`${area}m²`:'未入力'}`}return '測定値なし'}
function renderEquipmentList(){const list=$('#equipmentList');const marks=[...(state.project?.markers||[])].sort((a,b)=>markerTag(a).localeCompare(markerTag(b),'ja',{numeric:true}));if(!marks.length){list.innerHTML='<div class="list-empty">まだ設備がありません</div>';return}list.innerHTML=marks.map(m=>{const t=getType(m.typeId);const issue=m.findings?.length||0;const findings=(m.findings||[]).map(f=>`${f.severity}${f.title?`：${f.title}`:''}`).filter(Boolean).join(' ／ ');return `<div class="equip-row ${state.selectedMarker===m.id?'selected':''}" data-id="${m.id}"><span class="equip-icon" data-category="${t.category}" style="--type-color:${escapeHtml(t.color||'#1769aa')};color:${escapeHtml(t.textColor||(t.category==='light'?'#26394a':'#ffffff'))}">${glyphHtml(t)}</span><div class="equip-row-main"><strong>${escapeHtml(markerTag(m,t))}　${escapeHtml(t.name)}</strong><small>${escapeHtml(pageName(m.page))}${m.memo?` ・${escapeHtml(m.memo)}`:''}</small><small class="result-details">${escapeHtml(markerResultSummary(m,t))}</small>${issue?`<small class="result-findings">報告 ${issue}件：${escapeHtml(findings)}</small>`:''}</div><span class="mini-status ${hasNg(m)?'ng':m.checked?'checked':''}" title="${m.checked?'点検済':'未点検'}">${m.checked?'✓':''}</span></div>`}).join('');list.querySelectorAll('.equip-row').forEach(r=>r.onclick=()=>navigateToMarker(r.dataset.id))}
