function setupDrawingTouchGestures(){
  const area=$('#drawingArea'),wrap=$('#pageWrap');
  const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  const midpoint=(a,b)=>({x:(a.x+b.x)/2,y:(a.y+b.y)/2});
  const localPoint=(client,rect)=>({x:client.x-rect.left,y:client.y-rect.top});
  area.addEventListener('pointerdown',e=>{
    if(e.pointerType!=='touch'||!state.pdf||!wrap.contains(e.target))return;
    drawingPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
    if(!e.target.closest('.map-marker,.field-map-marker')){try{area.setPointerCapture(e.pointerId)}catch{}}
    if(drawingPointers.size===1&&!e.target.closest('.map-marker,.field-map-marker'))touchPan={id:e.pointerId,startX:e.clientX,startY:e.clientY,scrollLeft:area.scrollLeft,scrollTop:area.scrollTop,moved:false};
    if(drawingPointers.size===2){
      const pts=[...drawingPointers.values()],center=midpoint(pts[0],pts[1]),rect=wrap.getBoundingClientRect(),port=area.getBoundingClientRect();
      const portLeft=port.left+area.clientLeft,portTop=port.top+area.clientTop;
      pinchGesture={startDistance:Math.max(1,distance(pts[0],pts[1])),startZoom:state.zoom,zoom:state.zoom,startCenter:center,center,
        anchorPageX:(center.x-rect.left)/state.scale,anchorPageY:(center.y-rect.top)/state.scale,
        viewX:center.x-portLeft,viewY:center.y-portTop};
      pinchSessionActive=true;touchPan=null;wrap.style.transformOrigin=`${center.x-rect.left}px ${center.y-rect.top}px`;e.preventDefault();
    }
  },true);
  area.addEventListener('pointermove',e=>{
    if(!drawingPointers.has(e.pointerId))return;
    drawingPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
    if(pinchGesture&&drawingPointers.size>=2){
      const pts=[...drawingPointers.values()],center=midpoint(pts[0],pts[1]),ratio=distance(pts[0],pts[1])/pinchGesture.startDistance;
      pinchGesture.zoom=Math.max(ZOOM_MIN,Math.min(ZOOM_MAX,pinchGesture.startZoom*ratio));pinchGesture.center=center;
      wrap.style.transform=`translate(${center.x-pinchGesture.startCenter.x}px,${center.y-pinchGesture.startCenter.y}px) scale(${pinchGesture.zoom/pinchGesture.startZoom})`;
      e.preventDefault();return;
    }
    if(touchPan&&touchPan.id===e.pointerId){
      const dx=e.clientX-touchPan.startX,dy=e.clientY-touchPan.startY;
      if(Math.abs(dx)+Math.abs(dy)>6)touchPan.moved=true;
      if(touchPan.moved){const panSpeed=1.25;area.scrollLeft=touchPan.scrollLeft-dx*panSpeed;area.scrollTop=touchPan.scrollTop-dy*panSpeed;e.preventDefault()}
    }
  },{capture:true,passive:false});
  const end=e=>{
    if(!drawingPointers.has(e.pointerId))return;
    drawingPointers.delete(e.pointerId);
    if(pinchGesture&&drawingPointers.size<2){
      const final={...pinchGesture},finalZoom=final.zoom;pinchGesture=null;wrap.style.transform='';wrap.style.transformOrigin='';ignoreGestureClickUntil=Date.now()+700;
      if(Math.abs(finalZoom-state.zoom)>.01){
        state.zoom=finalZoom;
        renderPage(state.pdfPage).then(()=>requestAnimationFrame(()=>{
          const port=area.getBoundingClientRect(),rect=wrap.getBoundingClientRect(),portLeft=port.left+area.clientLeft,portTop=port.top+area.clientTop;
          area.scrollLeft=Math.max(0,Math.min(area.scrollWidth-area.clientWidth,area.scrollLeft+(rect.left-portLeft)+final.anchorPageX*state.scale-(final.center.x-portLeft)));
          area.scrollTop=Math.max(0,Math.min(area.scrollHeight-area.clientHeight,area.scrollTop+(rect.top-portTop)+final.anchorPageY*state.scale-(final.center.y-portTop)));
        }));
      }
    }
    if(touchPan&&touchPan.id===e.pointerId){if(touchPan.moved)ignoreGestureClickUntil=Date.now()+700;touchPan=null}
    if(drawingPointers.size===0)setTimeout(()=>{if(drawingPointers.size===0)pinchSessionActive=false},0);
  };
  area.addEventListener('pointerup',end,true);area.addEventListener('pointercancel',end,true);
}
