function exportCsv(){const p=state.project;const heads=['整理記号','整理番号','設備種別','PDFページ','ページ名','設置位置メモ','部位','高さ(m)','幅(m)','閉鎖時間(秒)','閉鎖力(N)','危害防止装置','点検済み','不良箇所','追加記録','風速1(m/s)','風速2(m/s)','風速3(m/s)','風速4(m/s)','風速5(m/s)','風速平均(m/s)','開口面積(m²)','区分','不備内容','備考','写真ファイル名','改善提案（写真報告備考）'];const rows=[];for(const m of [...p.markers].sort((a,b)=>markerTag(a).localeCompare(markerTag(b),'ja',{numeric:true}))){const t=getType(m.typeId);const comps=m.components?.length?m.components:[{label:'',height:m.height,width:m.width}];for(const c of comps){const findings=m.findings?.length?m.findings:[{}];for(const f of findings){const v=m.velocities||[];const avg=average(v);const photoNames=(f.photos||[]).map((ph,i)=>photoFilename(t,m,f,ph,i)).join(' / ');rows.push([m.mark||t.mark||'',m.serial,t.name,m.page,pageName(m.page),m.memo,c.label,c.height,c.width,c.time,c.force,c.hazard,m.checked?'済':'未',f.part||'',Object.entries(m.extraValues||{}).map(([k,v])=>`${k}:${v}`).join(' / '),...[0,1,2,3,4].map(i=>v[i]||''),avg===null?'':avg.toFixed(2),calcAreaRaw(m.height,m.width),f.severity||'',f.title||'',f.detail||'',photoNames,findingReportRemark(f)])}}}const csv='\ufeff'+[heads,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),`${safeFilename(p.name||'測定一覧')}_測定一覧.csv`);showToast('整理番号順のCSVを書き出しました')}
function calcAreaRaw(h,w){return Number(h)>0&&Number(w)>0?(Number(h)*Number(w)).toFixed(2):''}
function photoFilename(t,m,f,ph,i){const parts=[...(m.floorNoteId?[safeFilename(pageName(m.page)),safeFilename(m.memo||'場所未入力')]:[]),safeFilename(t.name),safeFilename(markerTag(m,t)),safeFilename(f.title||f.severity||'写真')].filter(Boolean);const core=(m.floorNoteId?parts.map(x=>x.slice(0,32)):parts).join('_');return `${core}${i?`(${i+1})`:''}.jpg`}
