function exportPageCountsCsv(){const pages=state.pdf?.numPages||Math.max(0,...(state.project?.markers||[]).map(m=>Number(m.page)||0));if(!pages){showToast('ページ情報がありません');return}const rows=[['ページ','ページ名','設備名','整理記号','数量','単位']];for(let page=1;page<=pages;page++)for(const {type,count} of pageEquipmentCounts(page))rows.push([page,pageName(page),type.name,type.mark||'',count,countUnit(type)]);const csv='\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),`${safeFilename(state.project.name||'設備数量')}_ページ別設備数量.csv`);showToast('ページ別設備数量CSVを書き出しました')}

function submissionSettingsHtml(){
  const markers=[...(state.project?.markers||[])].filter(m=>!m.floorNoteId).sort((a,b)=>Number(a.page)-Number(b.page)||markerTag(a).localeCompare(markerTag(b),'ja',{numeric:true}));
  if(!markers.length)return '<div class="list-empty">図面上に設備を配置すると設定できます。</div>';
  return `<p class="master-intro">報告があるページだけを印刷します。図面上は整理番号を表示し、報告箇所に「！」、写真がある箇所に番号なしのカメラ印を付けます。写真番号は付けず、位置確認用として使う想定です。</p><label class="draw-only-reported"><input type="checkbox" data-draw-only-reported ${state.project?.submissionOptions?.onlyReported!==false?'checked':''}>報告を登録した設備だけを図面に表示</label><div class="draw-export-list">${markers.map(m=>{const t=getType(m.typeId),conf=m.submission||{};const findings=(m.findings||[]).map((f,index)=>({f,index})).filter(({f})=>f.severity!=='メモ'&&f.severity!=='参考写真');return `<section class="draw-export-item"><label class="draw-export-equipment"><input type="checkbox" data-draw-marker="${escapeHtml(m.id)}" ${conf.showMarker!==false?'checked':''}><span class="export-type-icon" style="--type-color:${escapeHtml(t.color||'#1769aa')}">${glyphHtml(t)}</span><strong>${escapeHtml(markerTag(m,t))}　${escapeHtml(t.name)}</strong><small>${escapeHtml(pageName(m.page))}${m.memo?` ・${escapeHtml(m.memo)}`:''}</small></label>${findings.length?findings.map(({f,index})=>{const defaultShow=f.submissionShow??!!(f.title||f.detail);const text=f.submissionText??(f.title||f.detail||'');return `<div class="draw-export-finding"><label><input type="checkbox" data-draw-finding="${escapeHtml(m.id)}:${index}" ${defaultShow?'checked':''}>報告を表示</label><input type="text" data-draw-text="${escapeHtml(m.id)}:${index}" value="${escapeHtml(text)}" placeholder="図面の下の報告一覧に載せる文言"></div>`}).join(''):'<div class="draw-export-finding muted">報告内容は未登録です</div>'}</section>`}).join('')}</div><p class="modal-hint">図面は元PDFのページ画像を使います。ブラウザーの印刷画面からPDF保存できます。</p>`
}
function openSubmissionSettings(){
  if(!state.pdf||!state.project?.pdfBlob){showToast('先に図面PDFを読み込んでください');return}
  showModal('指摘箇所確認図の設定',submissionSettingsHtml(),()=>{
    const form=$('#modalRoot');
    state.project.submissionOptions={...(state.project.submissionOptions||{}),onlyReported:form.querySelector('[data-draw-only-reported]')?.checked!==false};
    for(const m of state.project.markers.filter(m=>!m.floorNoteId)){const box=form.querySelector(`[data-draw-marker="${CSS.escape(m.id)}"]`);m.submission=m.submission||{};m.submission.showMarker=box?box.checked:true;for(let i=0;i<(m.findings||[]).length;i++){const key=`${m.id}:${i}`,check=form.querySelector(`[data-draw-finding="${CSS.escape(key)}"]`),text=form.querySelector(`[data-draw-text="${CSS.escape(key)}"]`);if(check)m.findings[i].submissionShow=check.checked;if(text)m.findings[i].submissionText=text.value.trim()}}
    saveSoon();closeModal();openSubmissionDrawing();
  });
  $('#modalSave').textContent='図面を作成';
}
function drawingReportRecords(){
  const selected=reportRecords(state.project).filter(r=>!r.m.floorNoteId&&r.f.severity!=='メモ'&&r.f.severity!=='参考写真'&&r.f.submissionShow!==false).map(r=>({...r,text:String(r.f.submissionText??(r.title||r.detail||'')).trim()})).filter(r=>r.text);
  const numbers=new Map();let next=1;
  return selected.map(r=>{const key=JSON.stringify([r.f.severity||'',r.text]);if(!numbers.has(key))numbers.set(key,next++);const photos=[];for(let i=0;i<(r.f.photos||[]).length;i++)photos.push(i+1);return {...r,number:numbers.get(key),m:r.m,t:r.t,f:r.f,photos}});
}
