  root.querySelectorAll('[data-floor-slot]').forEach(b=>b.onclick=()=>{const id=b.dataset.floorSlot;if(state.floorSelecting){state.floorSelection=selected.has(id)?state.floorSelection.filter(x=>x!==id):[...state.floorSelection,id];renderFloorBoard()}else openFloorSlot(floor.id,id)});
