  state.floorUndo={projectId:state.project.id,floorId,slots:structuredClone(slots),markers:structuredClone(markers),media:Object.fromEntries([...photoIds].filter(id=>state.project.media?.[id]).map(id=>[id,state.project.media[id]]))};
  state.project.markers=state.project.markers.filter(m=>!markerIds.has(m.id));for(const s of slots)s.markerId='';
