  if(t.form==='door')for(const c of m.components||[]){const values=[c.height!==''&&c.height!=null?`高さ ${c.height}m`:'',c.width!==''&&c.width!=null?`幅 ${c.width}m`:'',c.time!==''&&c.time!=null?`閉鎖時間 ${c.time}秒`:'',c.force!==''&&c.force!=null?`閉鎖力 ${c.force}N`:'',c.hazard?`危害防止 ${c.hazard}`:''].filter(Boolean);if(values.length)lines.push(`${c.label||'扉'}：${values.join(' ／ ')}`)}
  if(t.form==='smokeOutlet'){if(String(m.height??'')!==''||String(m.width??'')!=='')lines.push(`縦 ${m.height||'未入力'}m ／ 横 ${m.width||'未入力'}m`);const vals=(m.velocities||[]).map(v=>String(v??'')).filter(v=>v!==''),avg=average(m.velocities||[]);if(vals.length)lines.push(`風速5点：${(m.velocities||[]).map(v=>v===''?'未入力':`${v}m/s`).join(' ／ ')}${avg===null?'':` ／ 平均 ${avg.toFixed(2)}m/s`}`);const area=calcAreaRaw(m.height,m.width);if(area)lines.push(`開口面積 ${area}m²`)}
  for(const [key,value] of Object.entries(m.extraValues||{}))if(String(value??'').trim())lines.push(`${key}：${value}`);return lines;
