        const perPage=options.photoCount===4?4:6;for(let i=0;i<cards.length;i+=perPage){const chunk=cards.slice(i,i+perPage),rows=[];for(let j=0;j<chunk.length;j+=2)rows.push(`<div class="photo-index-row">${chunk.slice(j,j+2).join('')}</div>`);photoPages.push(`<section class="photo-index-page ${perPage===4?'four-photos':''}"><h2>写真一覧　${escapeHtml(floor.name)}</h2>${rows.join('')}</section>`)}
