function bindFloorReportEditor(win,initial){
  let revision=initial.revision,dirty=false,saving=false,replace=initial.replace,editEpoch=0;
  const doc=win.document,status=doc.querySelector('#floorReportStatus'),button=doc.querySelector('#saveFloorReportDraft');
  const updateEmpty=()=>doc.querySelectorAll('.report-optional').forEach(section=>section.classList.toggle('is-empty',!section.querySelector('[data-floor-report-key]').innerText.trim()));updateEmpty();
  doc.querySelectorAll('[data-floor-report-key]').forEach(el=>{
    el.addEventListener('input',()=>{editEpoch++;dirty=true;status.textContent='未保存の編集があります。保存すると、次回も続きを編集できます。';updateEmpty()});
    el.addEventListener('paste',event=>{event.preventDefault();const text=event.clipboardData?.getData('text/plain')||'',selection=win.getSelection();if(!selection?.rangeCount)return;const range=selection.getRangeAt(0);range.deleteContents();const node=doc.createTextNode(text);range.insertNode(node);range.setStartAfter(node);range.collapse(true);selection.removeAllRanges();selection.addRange(range);el.dispatchEvent(new win.Event('input',{bubbles:true}))});
  });
  const save=async()=>{if(saving)return false;saving=true;button.disabled=true;const epoch=editEpoch,fields={};doc.querySelectorAll('[data-floor-report-key]').forEach(el=>fields[el.dataset.floorReportKey]=el.innerText.replace(/\r\n/g,'\n'));const result=await saveFloorReportDraft(initial.projectId,revision,fields,replace);saving=false;button.disabled=false;status.textContent=result.message;if(result.ok){revision=result.revision;dirty=editEpoch!==epoch;replace=false;if(dirty)status.textContent='保存後に追加の編集があります。もう一度保存してください。'}return result.ok};
  button.onclick=save;doc.querySelector('#printFloorReport').onclick=async()=>{if(dirty&&(!await save()||dirty))return;win.print()};
  win.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue=''}});
}
